#define ALARM_BUZZER_GROUP_TICKS \
    ((ALARM_BUZZER_BEEP_COUNT * ALARM_BUZZER_BEEP_STEP_TICKS) + \
     ALARM_BUZZER_GROUP_PAUSE_TICKS)
